// Build-time Latin -> Deseret, from the word table generated by scripts/deseret-words.mjs.
// Mirrors the client toggle in src/scripts/site.js: unknown words stay in Latin letters.
import WORDS from '../data/deseret-words.json';

const CASE_OFFSET = 0x28; // capitals sit 0x28 below lowercase
const WORD_RE = /[A-Za-z]+(?:['’][A-Za-z]+)*/g;
const upper = (s) => Array.from(s).map((c) => String.fromCodePoint(c.codePointAt(0) - CASE_OFFSET)).join('');

export function dsrtWord(w) {
  const d = WORDS[w.toLowerCase().replace(/’/g, "'")];
  if (!d) return null;
  if (w.length > 1 && w === w.toUpperCase()) return upper(d);
  if (w[0] !== w[0].toLowerCase()) { const [first, ...rest] = Array.from(d); return upper(first) + rest.join(''); }
  return d;
}

/** Whole string; unknown words are kept as they are. */
export function toDeseret(text) {
  return text.replace(WORD_RE, (w) => dsrtWord(w) ?? w);
}

/** Parts for the title reveal, or null if any word is unknown (then no reveal). */
export function revealParts(text) {
  const parts = [];
  for (const p of text.split(/(\s+)/)) {
    if (!p) continue;
    if (/^\s+$/.test(p)) { parts.push(null); continue; }
    let ok = true;
    const d = p.replace(WORD_RE, (w) => dsrtWord(w) ?? ((ok = false), w));
    if (!ok) return null;
    parts.push(d);
  }
  return parts;
}
